package vn.eventplatform.ad.config; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer; import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity public class SecurityConfiguration { @Bean SecurityFilterChain filter(HttpSecurity h)throws Exception{return h.csrf(AbstractHttpConfigurer::disable).authorizeHttpRequests(a->a.requestMatchers("/api/v1/public/**","/internal/**").permitAll().anyRequest().authenticated()).build();}}
